INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000727', 'Manakah parameter yang dibutuhkan dalam persamaan Archie untuk menghitung Sw?', 'Which parameters are required in Archie''s equation to calculate Sw?', 'multi', 'PFC000000005', 'Soal Inisialisasi', 'a:4:{i:0;s:14:"Porositas (φ)";i:1;s:25:"Resistivitas formasi (Rt)";i:2;s:29:"Resistivitas air formasi (Rw)";i:3;s:22:"Eksponen sementasi (m)";}', 'a:4:{i:0;s:13:"Porosity (φ)";i:1;s:26:"Formation resistivity (Rt)";i:2;s:32:"Formation water resistivity (Rw)";i:3;s:24:"Cementation exponent (m)";}', '', 'a:4:{i:0;s:14:"Porositas (φ)";i:1;s:25:"Resistivitas formasi (Rt)";i:2;s:29:"Resistivitas air formasi (Rw)";i:3;s:22:"Eksponen sementasi (m)";}', 'a:4:{i:0;s:13:"Porosity (φ)";i:1;s:26:"Formation resistivity (Rt)";i:2;s:32:"Formation water resistivity (Rw)";i:3;s:24:"Cementation exponent (m)";}', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
