INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000736', 'Zona dengan porositas rendah, Vsh tinggi, dan Sw tinggi sebaiknya...', 'A zone with low porosity, high Vsh, and high Sw should be...', 'option', 'PFC000000005', 'Final Test Advanced', 'a:4:{i:0;s:36:"Dikeluarkan dari perhitungan net pay";i:1;s:30:"Dihitung sebagai net pay penuh";i:2;s:17:"Dianggap zona gas";i:3;s:20:"Dianggap zona minyak";}', 'a:4:{i:0;s:37:"Excluded from the net pay calculation";i:1;s:23:"Counted as full net pay";i:2;s:21:"Considered a gas zone";i:3;s:22:"Considered an oil zone";}', '', 'Dikeluarkan dari perhitungan net pay', 'Excluded from the net pay calculation', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000737', 'Koreksi efek gas pada neutron-density dilakukan karena gas...', 'Gas effect correction on neutron-density is performed because gas...', 'option', 'PFC000000005', 'Final Test Advanced', 'a:4:{i:0;s:68:"Menurunkan pembacaan neutron sehingga porositas terlihat lebih besar";i:1;s:26:"Menaikkan densitas matriks";i:2;s:33:"Menghilangkan sinyal resistivitas";i:3;s:26:"Menambah kandungan lempung";}', 'a:4:{i:0;s:53:"Lowers the neutron reading so porosity appears larger";i:1;s:24:"Increases matrix density";i:2;s:30:"Removes the resistivity signal";i:3;s:22:"Increases clay content";}', '', 'Menurunkan pembacaan neutron sehingga porositas terlihat lebih besar', 'Lowers the neutron reading so porosity appears larger', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
