INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000741', 'Pada batupasir lempungan, penggunaan persamaan Archie langsung tanpa koreksi lempung umumnya...', 'In shaly sandstone, using Archie''s equation directly without clay correction generally...', 'option', 'PFC000000005', 'Final Test Advanced', 'a:4:{i:0;s:35:"Menghasilkan Sw yang terlalu tinggi";i:1;s:35:"Menghasilkan Sw yang terlalu rendah";i:2;s:17:"Tidak berpengaruh";i:3;s:30:"Menghasilkan porositas negatif";}', 'a:4:{i:0;s:28:"Produces Sw that is too high";i:1;s:27:"Produces Sw that is too low";i:2;s:13:"Has no effect";i:3;s:26:"Produces negative porosity";}', '', 'Menghasilkan Sw yang terlalu tinggi', 'Produces Sw that is too high', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
